102	// without any opening bracket or quote. "U.S.A." style initialisms are not
103	// listed: they usually do end a sentence when they come last, and guessing
104	// otherwise would trade one error for another.
105	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
106	
107	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
108	// only where whitespace or the end of the text follows. Requiring that keeps
109	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
110	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
111	
112	function endsWithAbbreviation(before) {
113	  const last = before.match(/(\S+)$/);
114	  if (last === null) {
